These five snippets are the canonical answers learners should write from memory.

```java
// 1. Remove every x from an ArrayList<Integer>: removeIf, or an explicit iterator.
list.removeIf(v -> v == x); // x is an int, so v is unboxed and compared by value
for (Iterator<Integer> it = list.iterator(); it.hasNext(); ) {
    if (it.next() == x) it.remove();
}

// 2. Remove every x from an int[] in O(n): compact with a write pointer.
int w = 0;
for (int r = 0; r < a.length; r++) if (a[r] != x) a[w++] = a[r];
int[] trimmed = Arrays.copyOf(a, w); // arrays cannot shrink; copy if a trimmed array is needed

// 3. Safe circular index, even for negative i.
int wrapped = Math.floorMod(i, n);

// 4. Overflow-safe midpoint and total.
int mid = lo + (hi - lo) / 2;
long total = 0;
for (int v : a) total += v;

// 5. Rotate right by k in place with three reversals.
static void rotate(int[] a, int k) {
    int n = a.length;
    if (n == 0) return;
    k = Math.floorMod(k, n);
    reverse(a, 0, n - 1);
    reverse(a, 0, k - 1);
    reverse(a, k, n - 1);
}

static void reverse(int[] a, int l, int r) {
    for (; l < r; l++, r--) {
        int t = a[l];
        a[l] = a[r];
        a[r] = t;
    }
}
```

