Java · Java Bits and Bit Manipulation · Bit idioms track
Five snippets solve the corpus's bit problems, plus Sum of Two Integers from NeetCode 150.

```java
// Single Number: XOR cancels every value that appears twice.
static int singleNumber(int[] nums) {
    int x = 0;
    for (int v : nums) x ^= v;
    return x;
}

// Number of 1 Bits: the input is treated as unsigned, so loop while n != 0, never n > 0.
static int hammingWeight(int n) {
    int count = 0;
    while (n != 0) {
        n &= n - 1; // clear the lowest set bit
        count++;
    }
    return count;
}

// Counting Bits: reuse the count of i >> 1.
static int[] countBits(int n) {
    int[] bits = new int[n + 1];
    for (int i = 1; i <= n; i++) bits[i] = bits[i >> 1] + (i & 1);
    return bits;
}

// Reverse Bits: exactly 32 steps, shifting the input with >>> so no sign bits are copied in.
static int reverseBits(int n) {
    int res = 0;
    for (int i = 0; i < 32; i++) {
        res = (res << 1) | (n & 1);
        n >>>= 1;
    }
    return res; // or Integer.reverse(n)
}

// Missing Number: XOR every index and every value; the missing one is left over.
static int missingNumber(int[] nums) {
    int x = nums.length;
    for (int i = 0; i < nums.length; i++) x ^= i ^ nums[i];
    return x;
}

// Sum of Two Integers (150): repeat until there is no carry; works for negatives because int wraps.
static int getSum(int a, int b) {
    while (b != 0) {
        int carry = (a & b) << 1;
        a ^= b;
        b = carry;
    }
    return a;
}
```

