// 1. Edge list -> adjacency list of {neighbour, weight} pairs.
static List<List<int[]>> buildAdj(int n, int[][] edges, boolean directed) {
    List<List<int[]>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) adj.add(new ArrayList<>()); // one independent list per node
    for (int[] e : edges) {
        int w = e.length > 2 ? e[2] : 1;
        adj.get(e[0]).add(new int[] {e[1], w});
        if (!directed) adj.get(e[1]).add(new int[] {e[0], w});
    }
    return adj;
}

// 2. BFS: fewest edges from source to every node (-1 when unreachable).
static int[] bfsDistances(List<List<Integer>> adj, int source) {
    int[] dist = new int[adj.size()];
    Arrays.fill(dist, -1);
    dist[source] = 0;
    Deque<Integer> queue = new ArrayDeque<>();
    queue.offer(source);
    while (!queue.isEmpty()) {
        int u = queue.poll();
        for (int v : adj.get(u)) {
            if (dist[v] == -1) { dist[v] = dist[u] + 1; queue.offer(v); } // mark when offered
        }
    }
    return dist;
}
```

