Java · Java Graphs · Algorithm choice track
Four snippets cover the algorithms specific to graphs; Dijkstra is in the Java heap blueprint.

```java
// 1. Kahn's topological sort: edges[i] = {from, to}, meaning from must come first.
static int[] topoOrder(int n, int[][] edges) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
    int[] indegree = new int[n];
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);
        indegree[e[1]]++;
    }
    Deque<Integer> queue = new ArrayDeque<>();
    for (int i = 0; i < n; i++) if (indegree[i] == 0) queue.offer(i);
    int[] order = new int[n];
    int k = 0;
    while (!queue.isEmpty()) {
        int u = queue.poll();
        order[k++] = u;
        for (int v : adj.get(u)) if (--indegree[v] == 0) queue.offer(v);
    }
    return k == n ? order : new int[0]; // fewer than n nodes means a cycle
}

// 2. Directed cycle check with three states: 0 unvisited, 1 on the current path, 2 done.
static boolean hasCycle(List<List<Integer>> adj) {
    int[] state = new int[adj.size()];
    for (int i = 0; i < adj.size(); i++) if (state[i] == 0 && dfs(adj, i, state)) return true;
    return false;
}

private static boolean dfs(List<List<Integer>> adj, int u, int[] state) {
    state[u] = 1;
    for (int v : adj.get(u)) {
        if (state[v] == 1) return true; // back on the current path
        if (state[v] == 0 && dfs(adj, v, state)) return true;
    }
    state[u] = 2;
    return false;
}
```

