            x = parent[x];
        }
        return x;
    }

    boolean union(int a, int b) { // false when already connected: this edge closes a cycle
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        size[ra] += size[rb];
        count--;
        return true;
    }

    int count() { return count; }
}
```

