static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
static int landNeighbours(char[][] grid, int r, int c) {
  int m = grid.length, n = grid[0].length, count = 0;
  for (int[] d : DIRS) {
    int nr = r + d[0], nc = c + d[1];
    if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == '1') count++;
  }
  return count;
}
