// 1. Bounds and neighbours with a direction array.
static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

static boolean inBounds(int r, int c, int m, int n) {
    return r >= 0 && r < m && c >= 0 && c < n;
}

// 2. Deep copy: clone each row, because grid.clone() shares them.
static int[][] deepCopy(int[][] grid) {
    int[][] copy = new int[grid.length][];
    for (int i = 0; i < grid.length; i++) copy[i] = grid[i].clone();
    return copy;
}

// 3. Flat index <-> (row, column) for an m x n grid.
static int toIndex(int r, int c, int n) { return r * n + c; }
static int rowOf(int i, int n) { return i / n; }
static int colOf(int i, int n) { return i % n; }

// 4. Rotate a square matrix 90 degrees clockwise in place: transpose, then reverse each row.
static void rotate(int[][] matrix) {
    int size = matrix.length;
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            int t = matrix[i][j];
            matrix[i][j] = matrix[j][i];
            matrix[j][i] = t;
        }
    }
    for (int[] row : matrix) {
        for (int l = 0, r = size - 1; l < r; l++, r--) {
            int t = row[l];
            row[l] = row[r];
            row[r] = t;
        }
    }
}
```

The `char` row deserves its own drill: LeetCode's Number of Islands and Word Search pass `char[][]` boards, and `grid[r][c] == 1` compiles, runs, and silently finds no land.

