```java
// 1. Iterative flood fill: area of the region of '1's containing (sr, sc). Safe on huge grids.
static int regionArea(char[][] grid, int sr, int sc) {
    int m = grid.length, n = grid[0].length;
    if (grid[sr][sc] != '1') return 0;
    boolean[][] seen = new boolean[m][n];
    Deque<int[]> stack = new ArrayDeque<>();
    stack.push(new int[] {sr, sc});
    seen[sr][sc] = true;
    int area = 0;
    while (!stack.isEmpty()) {
        int[] cell = stack.pop();
        area++;
        for (int[] d : DIRS) {
            int nr = cell[0] + d[0], nc = cell[1] + d[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && !seen[nr][nc] && grid[nr][nc] == '1') {
                seen[nr][nc] = true;
                stack.push(new int[] {nr, nc});
            }
        }
    }
    return area;
}

// 2. 2D prefix sums in long: any rectangle sum in O(1) after O(m * n) setup.
static long[][] prefix2D(int[][] a) {
    int m = a.length, n = a[0].length;
    long[][] p = new long[m + 1][n + 1];
    for (int r = 0; r < m; r++)
        for (int c = 0; c < n; c++)
            p[r + 1][c + 1] = a[r][c] + p[r][c + 1] + p[r + 1][c] - p[r][c];
    return p;
}

static long rectSum(long[][] p, int r1, int c1, int r2, int c2) { // inclusive corners
    return p[r2 + 1][c2 + 1] - p[r1][c2 + 1] - p[r2 + 1][c1] + p[r1][c1];
}
```

