class MedianFinder {
  public PriorityQueue<Integer> low = new PriorityQueue<>(Comparator.reverseOrder());
  public PriorityQueue<Integer> high = new PriorityQueue<>(); // callers can unbalance them
}
Correct:
class MedianFinder {
  private final PriorityQueue<Integer> low = new PriorityQueue<>(Comparator.reverseOrder());
  private final PriorityQueue<Integer> high = new PriorityQueue<>();
  public void addNum(int x) {
    low.offer(x);
    high.offer(low.poll());
    if (high.size() > low.size()) low.offer(high.poll());
  }
  public double findMedian() {
    return low.size() > high.size() ? low.peek() : (low.peek() + (double) high.peek()) / 2;
  }
}
Complexity: O(log n) per addNum, O(1) per findMedian

