// 2. Multi-source grid BFS: every 0 is a source; cells encoded as r * n + c.
static int[][] distances(int[][] grid) {
    int m = grid.length, n = grid[0].length;
    int[][] dist = new int[m][n];
    for (int[] row : dist) Arrays.fill(row, -1);
    Queue<Integer> queue = new ArrayDeque<>();
    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            if (grid[r][c] == 0) {
                dist[r][c] = 0;
                queue.offer(r * n + c);
            }
        }
    }
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!queue.isEmpty()) {
        int cell = queue.poll(), r = cell / n, c = cell % n;
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && dist[nr][nc] == -1) {
                dist[nr][nc] = dist[r][c] + 1; // mark when queued
                queue.offer(nr * n + nc);
            }
        }
    }
    return dist;
}
```

Snippet 1's `for (int size = queue.size(); ...)` loop is the Java idiom for level snapshots: the size is read once, so children added during the loop wait for the next level.

