Java · Java Segment Trees and Fenwick Trees · Segment tree track
Two snippets cover the two segment trees learners need: the compact iterative one for point updates, and the recursive one with lazy propagation for range updates.

```java
// 1. Iterative segment tree: point update, sum over the half-open range [l, r).
final class SegmentTree {
    private final int n;
    private final long[] t;

    SegmentTree(int[] a) {
        n = a.length;
        t = new long[2 * n];
        for (int i = 0; i < n; i++) t[n + i] = a[i];                  // leaves
        for (int i = n - 1; i > 0; i--) t[i] = t[2 * i] + t[2 * i + 1]; // parents
    }

    void set(int i, long value) {
        i += n;
        t[i] = value;
        for (i >>= 1; i >= 1; i >>= 1) t[i] = t[2 * i] + t[2 * i + 1];
    }

    long query(int l, int r) {
        long res = 0; // the identity for sums
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) res += t[l++];
            if ((r & 1) == 1) res += t[--r];
        }
        return res;
    }
}

// 2. Lazy segment tree: add v to every element of [l, r], and sum over [l, r] (inclusive).
final class LazySegmentTree {
    private final int n;
    private final long[] sum, lazy;

    LazySegmentTree(int n) {
        this.n = n;
        sum = new long[4 * n];
        lazy = new long[4 * n];
    }

    void add(int l, int r, long v) { add(1, 0, n - 1, l, r, v); }

    long query(int l, int r) { return query(1, 0, n - 1, l, r); }
```

