    private void add(int node, int lo, int hi, int l, int r, long v) {
        if (r < lo || hi < l) return;                              // no overlap
        if (l <= lo && hi <= r) { apply(node, lo, hi, v); return; } // fully covered: tag and stop
        push(node, lo, hi);
        int mid = (lo + hi) >>> 1;
        add(2 * node, lo, mid, l, r, v);
        add(2 * node + 1, mid + 1, hi, l, r, v);
        sum[node] = sum[2 * node] + sum[2 * node + 1];
    }

    private long query(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) return 0;
        if (l <= lo && hi <= r) return sum[node];
        push(node, lo, hi);
        int mid = (lo + hi) >>> 1;
        return query(2 * node, lo, mid, l, r) + query(2 * node + 1, mid + 1, hi, l, r);
    }

    private void apply(int node, int lo, int hi, long v) {
        sum[node] += v * (hi - lo + 1); // every element in the range grows by v
        lazy[node] += v;                // remember to pass v to the children later
    }

    private void push(int node, int lo, int hi) {
        if (lazy[node] == 0) return;
        int mid = (lo + hi) >>> 1;
        apply(2 * node, lo, mid, lazy[node]);
        apply(2 * node + 1, mid + 1, hi, lazy[node]);
        lazy[node] = 0;
    }
}
```

Snippet 1 works for any `n`, not just powers of two, and for any commutative operation: replace `+` and the identity 0 with `Math.min` and `Long.MAX_VALUE` for range minimum queries.

