```java
// 1. Duplicate detection with add's return value (Contains Duplicate).
static boolean containsDuplicate(int[] nums) {
    Set<Integer> seen = new HashSet<>();
    for (int x : nums) if (!seen.add(x)) return true; // false means x was already present
    return false;
}

// 2. Grid visited set with a record element, marked when queued.
record Cell(int r, int c) {}

Set<Cell> visited = new HashSet<>();
Deque<Cell> queue = new ArrayDeque<>();
Cell start = new Cell(0, 0);
visited.add(start);
queue.add(start);
while (!queue.isEmpty()) {
    Cell cur = queue.poll();
    for (int[] d : new int[][] {{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
        Cell next = new Cell(cur.r() + d[0], cur.c() + d[1]);
        if (inBounds(next) && visited.add(next)) queue.add(next); // add returns false if seen
    }
}

// 3. Count a run only from its first value (Longest Consecutive Sequence).
static int longestConsecutive(int[] nums) {
    Set<Integer> values = new HashSet<>();
    for (int x : nums) values.add(x);
    int best = 0;
    for (int x : values) {
        if (values.contains(x - 1)) continue;
