Java · Java Stacks · LIFO patterns track
Four snippets cover the patterns that need Java-specific care.

```java
// 1. Monotonic stack of indices: next greater element.
static int[] nextGreater(int[] nums) {
    int[] res = new int[nums.length];
    Arrays.fill(res, -1);
    Deque<Integer> stack = new ArrayDeque<>(); // indices whose values decrease from bottom to top
    for (int i = 0; i < nums.length; i++) {
        while (!stack.isEmpty() && nums[stack.peek()] < nums[i]) res[stack.pop()] = nums[i];
        stack.push(i);
    }
    return res;
}

// 2. Min stack: each entry carries the minimum at its height.
class MinStack {
    private final Deque<int[]> stack = new ArrayDeque<>(); // {value, minimum so far}

    public void push(int x) {
        int min = stack.isEmpty() ? x : Math.min(x, stack.peek()[1]);
        stack.push(new int[] {x, min});
    }

    public void pop() { stack.pop(); }
    public int top() { return stack.peek()[0]; }
    public int getMin() { return stack.peek()[1]; }
}
```

