// 4. Expand around a centre; afterwards the palindrome is s.substring(l + 1, r).
static String expand(String s, int l, int r) {
    while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) {
        l--;
        r++;
    }
    return s.substring(l + 1, r);
}

// 5. Split on a literal dot, keeping trailing empty fields.
