Four snippets are the canonical answers, one per contract shape.

```java
// 1. Return up.
static int maxDepth(TreeNode node) {
    if (node == null) return 0;
    return 1 + Math.max(maxDepth(node.left), maxDepth(node.right));
}

// 2. Pass down: long bounds, so Integer.MIN_VALUE and MAX_VALUE nodes are still valid.
static boolean isValidBST(TreeNode node, long low, long high) {
    if (node == null) return true;
    if (node.val <= low || node.val >= high) return false;
    return isValidBST(node.left, low, node.val) && isValidBST(node.right, node.val, high);
}
// call: isValidBST(root, Long.MIN_VALUE, Long.MAX_VALUE)

// 3. Combine children plus a global answer kept in a field.
class Diameter {
    private int best;

    int diameterOfBinaryTree(TreeNode root) {
        best = 0; // reset on every call
        depth(root);
        return best;
    }

    private int depth(TreeNode node) {
        if (node == null) return 0;
        int left = depth(node.left), right = depth(node.right);
        best = Math.max(best, left + right); // longest path bending here, in edges
        return 1 + Math.max(left, right);    // longest path continuing upward
    }
}

// 4. Two trees in step.
static boolean isSameTree(TreeNode p, TreeNode q) {
    if (p == null && q == null) return true;
    if (p == null || q == null || p.val != q.val) return false;
    return isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
}
```

