Java · Java Binary Trees · Variants and fit
Four snippets cover the operations that come with the rules.

```java
// 1. BST insert, recursively returning the (possibly new) subtree root.
static TreeNode insert(TreeNode node, int val) {
    if (node == null) return new TreeNode(val);
    if (val < node.val) node.left = insert(node.left, val);
    else node.right = insert(node.right, val);
    return node;
}

// 2. Lowest common ancestor: walk in a BST; recurse in any binary tree.
static TreeNode lcaBST(TreeNode root, TreeNode p, TreeNode q) {
    TreeNode node = root;
    while (node != null) {
        if (p.val < node.val && q.val < node.val) node = node.left;
        else if (p.val > node.val && q.val > node.val) node = node.right;
        else return node;
    }
    return null;
}

static TreeNode lca(TreeNode node, TreeNode p, TreeNode q) {
    if (node == null || node == p || node == q) return node; // == compares node identity
    TreeNode left = lca(node.left, p, q), right = lca(node.right, p, q);
    if (left != null && right != null) return node;
    return left != null ? left : right;
}

// 3. Height-balanced check in one pass: -1 means "already unbalanced below".
static boolean isBalanced(TreeNode root) {
    return height(root) != -1;
}
```

