Java · Java Tries · Node and path track
This class is the canonical Java trie; sections 3 and 10 build on its `Node`.

```java
class Trie {
    private static final class Node {
        final Node[] next = new Node[26]; // children for 'a'..'z'
        boolean end;                      // a word stops here
        int pass;                         // stored words whose path goes through this node
    }

    private final Node root = new Node();

    public void insert(String word) {
        if (search(word)) return; // keep pass counts exact on duplicates
        Node node = root;
        node.pass++;
        for (int i = 0; i < word.length(); i++) {
            int c = word.charAt(i) - 'a';
            if (node.next[c] == null) node.next[c] = new Node(); // create only if missing
            node = node.next[c];
            node.pass++;
        }
        node.end = true;
    }

    private Node find(String prefix) { // the node at the end of prefix, or null
        Node node = root;
        for (int i = 0; i < prefix.length() && node != null; i++) {
            node = node.next[prefix.charAt(i) - 'a'];
        }
        return node;
    }

    public boolean search(String word) {
        Node n = find(word);
        return n != null && n.end;
    }

    public boolean startsWith(String prefix) {
        return find(prefix) != null;
    }

    public int countWithPrefix(String prefix) {
        Node n = find(prefix);
        return n == null ? 0 : n.pass;
    }
```

