    private void dfs(char[][] board, int r, int c, Node parent, List<String> found) {
        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length) return;
        char ch = board[r][c];
        if (ch == '#') return;
        Node node = parent.next[ch - 'a'];
        if (node == null) return;
        if (node.word != null) { found.add(node.word); node.word = null; } // report once
        board[r][c] = '#';
        dfs(board, r + 1, c, node, found);
        dfs(board, r - 1, c, node, found);
        dfs(board, r, c + 1, node, found);
        dfs(board, r, c - 1, node, found);
        board[r][c] = ch; // restore the cell
        if (node.word == null && isLeaf(node)) parent.next[ch - 'a'] = null; // prune
    }

    private static boolean isLeaf(Node node) {
        for (Node child : node.next) if (child != null) return false;
        return true;
    }
}
