// 3. Autocomplete: up to `limit` words under a prefix, alphabetical for free with Node[26].
private static void collect(Node node, StringBuilder path, List<String> out, int limit) {
    if (out.size() >= limit) return;
    if (node.end) out.add(path.toString());
    for (int c = 0; c < 26; c++) {
        if (node.next[c] == null) continue;
        path.append((char) ('a' + c));
        collect(node.next[c], path, out, limit);
        path.setLength(path.length() - 1); // undo the append
    }
}
