// 1. Label keys: a HashMap parent, created lazily.
final class LabelUnionFind<T> {
    private final Map<T, T> parent = new HashMap<>();

    T find(T x) {
        parent.putIfAbsent(x, x);
        T root = x;
        while (!parent.get(root).equals(root)) root = parent.get(root);
        while (!parent.get(x).equals(root)) { // full path compression
            T next = parent.get(x);
            parent.put(x, root);
            x = next;
        }
        return root;
    }

    boolean union(T a, T b) {
        T ra = find(a), rb = find(b);
        if (ra.equals(rb)) return false;
        parent.put(ra, rb);
        return true;
    }
}

// 2. Number of Islands with union-find: islands = land cells - successful merges.
static int numIslands(char[][] grid) {
    int m = grid.length, n = grid[0].length, land = 0, merges = 0;
    UnionFind uf = new UnionFind(m * n);
    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            if (grid[r][c] != '1') continue;
            land++;
            if (r + 1 < m && grid[r + 1][c] == '1' && uf.union(r * n + c, (r + 1) * n + c)) merges++;
            if (c + 1 < n && grid[r][c + 1] == '1' && uf.union(r * n + c, r * n + c + 1)) merges++;
        }
    }
    return land - merges;
}
