// 3. Kruskal: edges[i] = {u, v, weight}; returns the MST weight, or -1 if disconnected.
static int kruskal(int n, int[][] edges) {
    int[][] sorted = edges.clone(); // sort a copy of the outer array; rows are only read
    Arrays.sort(sorted, Comparator.comparingInt(e -> e[2]));
    UnionFind uf = new UnionFind(n);
    int total = 0, used = 0;
    for (int[] e : sorted) {
        if (uf.union(e[0], e[1])) {
            total += e[2];
            if (++used == n - 1) break;
        }
    }
    return used == n - 1 ? total : -1;
}

// 4. Weighted union-find for a / b = ratio equations (Evaluate Division).
final class RatioUnionFind {
    private final Map<String, String> parent = new HashMap<>();
    private final Map<String, Double> weight = new HashMap<>(); // value(x) = weight(x) * value(parent(x))

    private void add(String x) {
        if (parent.putIfAbsent(x, x) == null) weight.put(x, 1.0);
    }

    private String find(String x) {
        String p = parent.get(x);
        if (!p.equals(x)) {
            String root = find(p);                         // p's weight is now relative to root
            weight.put(x, weight.get(x) * weight.get(p));
            parent.put(x, root);
        }
        return parent.get(x);
    }
