JavaScript · JavaScript Graphs · Representation and traversal track
These three snippets are the canonical answers learners should write from memory.

```javascript
// 1. Edge list -> adjacency list of [neighbour, weight] pairs.
function buildAdj(n, edges, directed = false) {
  const adj = Array.from({ length: n }, () => []); // one independent list per node
  for (const [u, v, w = 1] of edges) {
    adj[u].push([v, w]);
    if (!directed) adj[v].push([u, w]);
  }
  return adj;
}

// 2. BFS: fewest edges from source to every node (-1 when unreachable).
function bfsDistances(adj, source) {
  const dist = new Array(adj.length).fill(-1);
  dist[source] = 0;
  const queue = [source];
  for (let head = 0; head < queue.length; head++) {
    const u = queue[head];
    for (const [v] of adj[u]) {
      if (dist[v] === -1) { dist[v] = dist[u] + 1; queue.push(v); } // mark when queued
    }
  }
  return dist;
}

// 3. Iterative DFS over every node: count connected components.
function countComponents(adj) {
  const seen = new Array(adj.length).fill(false);
  let count = 0;
  for (let s = 0; s < adj.length; s++) {
    if (seen[s]) continue;
    count++;
    seen[s] = true;
    const stack = [s];
    while (stack.length) {
      const u = stack.pop();
      for (const [v] of adj[u]) if (!seen[v]) { seen[v] = true; stack.push(v); }
    }
  }
  return count;
}
```

Snippet 3's outer loop is the line learners most often leave out: without it, every node not reachable from the first start is silently ignored.

