```javascript
// 2. Kahn's topological sort: edges are [from, to], meaning from must come first.
function topoOrder(n, edges) {
  const adj = Array.from({ length: n }, () => []);
  const indegree = new Array(n).fill(0);
  for (const [u, v] of edges) { adj[u].push(v); indegree[v]++; }
  const queue = [];
  for (let i = 0; i < n; i++) if (indegree[i] === 0) queue.push(i);
  const order = [];
  for (let head = 0; head < queue.length; head++) {
    const u = queue[head];
    order.push(u);
    for (const v of adj[u]) if (--indegree[v] === 0) queue.push(v);
  }
  return order.length === n ? order : []; // fewer than n nodes means a cycle
}

// 3. Bipartite check: two-colour every component with BFS.
function isBipartite(adj) { // adj[u] is a list of neighbour ids
  const color = new Array(adj.length).fill(-1);
  for (let s = 0; s < adj.length; s++) {
    if (color[s] !== -1) continue;
    color[s] = 0;
    const queue = [s];
    for (let head = 0; head < queue.length; head++) {
      const u = queue[head];
      for (const v of adj[u]) {
        if (color[v] === -1) { color[v] = 1 - color[u]; queue.push(v); }
        else if (color[v] === color[u]) return false; // an edge inside one group
      }
    }
  }
  return true;
}
```

Union-find is the most reusable of the three: Number of Connected Components, Graph Valid Tree and Redundant Connection all reduce to counting groups or spotting the first `union` that returns `false`.

