```javascript
// 1. Iterative flood fill: area of the region containing (sr, sc), safe on very large grids.
function regionArea(grid, sr, sc, target) {
  const m = grid.length, n = grid[0].length;
  if (grid[sr][sc] !== target) return 0;
  const seen = new Uint8Array(m * n);
  const stack = [sr * n + sc];
  seen[sr * n + sc] = 1;
  let area = 0;
  while (stack.length) {
    const i = stack.pop(), r = Math.floor(i / n), c = i % n;
    area++;
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr, nc = c + dc, j = nr * n + nc;
      if (nr >= 0 && nr < m && nc >= 0 && nc < n && !seen[j] && grid[nr][nc] === target) {
        seen[j] = 1;
        stack.push(j);
      }
    }
  }
  return area;
}

// 2. 2D prefix sums: any rectangle sum in O(1) after O(m * n) setup.
function prefix2D(a) {
  const m = a.length, n = a[0].length;
  const P = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let r = 0; r < m; r++)
    for (let c = 0; c < n; c++) P[r + 1][c + 1] = a[r][c] + P[r][c + 1] + P[r + 1][c] - P[r][c];
  // sum of a[r1..r2][c1..c2], inclusive
  return (r1, c1, r2, c2) => P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1];
}
```

