This comparator-based class is the canonical implementation; every pattern in section 3 uses it.

```javascript
class Heap {
  #a = [];
  #cmp;

  constructor(cmp = (x, y) => x - y) { // min-heap by default; (x, y) => y - x for a max-heap
    this.#cmp = cmp;
  }

  get size() { return this.#a.length; }

  peek() { return this.#a[0]; }

  push(x) {
    const a = this.#a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.#cmp(a[i], a[p]) >= 0) break; // order already correct
      [a[i], a[p]] = [a[p], a[i]];
      i = p;
    }
  }

  pop() {
    const a = this.#a;
    if (a.length === 0) return undefined;
    const top = a[0];
    const last = a.pop();
    if (a.length > 0) {
      a[0] = last;
      this.#siftDown(0);
    }
    return top;
  }

  static heapify(items, cmp = (x, y) => x - y) { // O(n) bottom-up build
    const h = new Heap(cmp);
    h.#a = items.slice();
    for (let i = (h.#a.length >> 1) - 1; i >= 0; i--) h.#siftDown(i);
    return h;
  }

  #siftDown(i) {
    const a = this.#a;
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let best = i;
      if (l < a.length && this.#cmp(a[l], a[best]) < 0) best = l;
      if (r < a.length && this.#cmp(a[r], a[best]) < 0) best = r;
      if (best === i) return;
      [a[i], a[best]] = [a[best], a[i]];
      i = best;
    }
  }
}
```

Why heapify is O(n) is a good L1 question: most nodes sit near the bottom and sift only a step or two, so the total work sums to linear even though one sift can cost O(log n).

