Four snippets cover the patterns that show the heap's range; all use the `Heap` class from section 2.

```javascript
// 1. Top k largest: a size-k MIN-heap, because its top is the smallest of the k kept.
function topK(nums, k) {
  const h = new Heap((a, b) => a - b);
  for (const x of nums) {
    if (h.size < k) h.push(x);
    else if (x > h.peek()) { h.pop(); h.push(x); }
  }
  const out = [];
  while (h.size) out.push(h.pop());
  return out.reverse(); // largest first
}

// 2. k-way merge of sorted arrays: the heap holds one current head per array.
function mergeK(lists) {
  const h = new Heap((a, b) => a[0] - b[0]); // [value, listIndex, position]
  lists.forEach((list, i) => { if (list.length) h.push([list[0], i, 0]); });
  const out = [];
  while (h.size) {
    const [value, i, j] = h.pop();
    out.push(value);
    if (j + 1 < lists[i].length) h.push([lists[i][j + 1], i, j + 1]);
  }
  return out;
}
```

