```javascript
// 3. Running median with two heaps: every value in low <= every value in high.
class MedianFinder {
  #low = new Heap((a, b) => b - a);  // max-heap: smaller half
  #high = new Heap((a, b) => a - b); // min-heap: larger half
  addNum(x) {
    this.#low.push(x);
    this.#high.push(this.#low.pop()); // move the largest of the low half up
    if (this.#high.size > this.#low.size) this.#low.push(this.#high.pop()); // rebalance
  }
  findMedian() {
    return this.#low.size > this.#high.size
      ? this.#low.peek()
      : (this.#low.peek() + this.#high.peek()) / 2;
  }
}

// 4. Dijkstra: adj[u] is a list of [v, weight] pairs with non-negative weights.
function dijkstra(n, adj, source) {
  const dist = new Array(n).fill(Infinity);
  dist[source] = 0;
  const pq = new Heap((a, b) => a[0] - b[0]); // [distance, node]
  pq.push([0, source]);
  while (pq.size) {
    const [d, u] = pq.pop();
    if (d > dist[u]) continue; // stale entry: a shorter path was found after it was pushed
    for (const [v, w] of adj[u]) {
      if (d + w < dist[v]) {
        dist[v] = d + w;
        pq.push([dist[v], v]);
      }
    }
  }
  return dist;
}
```

Snippet 1's heap direction is the most tested idea in this track: the k largest live in a min-heap, because the item you may need to evict is the smallest of them.

