These five snippets are the canonical answers learners should write from memory.

```javascript
// 1. Reverse in place: save next, rewire, advance.
function reverse(head) {
  let prev = null, curr = head;
  while (curr) {
    const next = curr.next;
    curr.next = prev;
    prev = curr;
    curr = next;
  }
  return prev;
}

// 2. Remove every node with value v: a dummy head makes the head an ordinary node.
function removeAll(head, v) {
  const dummy = { val: 0, next: head };
  let prev = dummy;
  while (prev.next) {
    if (prev.next.val === v) prev.next = prev.next.next; // stay: the new next may match too
    else prev = prev.next;
  }
  return dummy.next;
}

// 3. Split into halves at the first middle; the first half gets the extra node.
function splitHalf(head) { // head is not null
  let slow = head, fast = head;
  while (fast.next && fast.next.next) { slow = slow.next; fast = fast.next.next; }
  const second = slow.next;
  slow.next = null; // cut, or the halves stay joined
  return second;
}

// 4. Merge two sorted lists with a dummy tail.
function merge(a, b) {
  const dummy = { val: 0, next: null };
  let tail = dummy;
  while (a && b) {
    if (a.val <= b.val) { tail.next = a; a = a.next; }
    else { tail.next = b; b = b.next; }
    tail = tail.next;
  }
  tail.next = a ?? b;
  return dummy.next;
}
```

