JavaScript · JavaScript Linked Lists (Singly, Doubly, Circular) · Doubly and circular variants track
Three snippets cover the variants: a doubly linked list with a single sentinel (which also makes it circular), an LRU cache built on it, and the Josephus problem on a circular singly linked list.

```javascript
// 1. Circular doubly linked list with one sentinel: no null checks anywhere.
class DNode {
  constructor(val) { this.val = val; this.prev = this; this.next = this; }
}

class DoublyList {
  #sentinel = new DNode(null); // sentinel.next is the first node, sentinel.prev the last
  #size = 0;

  get size() { return this.#size; }

  #insertAfter(at, node) {
    node.prev = at;           // the new node's references first...
    node.next = at.next;
    at.next.prev = node;      // ...then the neighbours'
    at.next = node;
    this.#size++;
    return node;
  }

  pushFront(val) { return this.#insertAfter(this.#sentinel, new DNode(val)); }
  pushBack(val) { return this.#insertAfter(this.#sentinel.prev, new DNode(val)); }

  remove(node) { // O(1) given the node itself
    node.prev.next = node.next;
    node.next.prev = node.prev;
    node.prev = node.next = node; // detach
    this.#size--;
    return node.val;
  }

  moveToFront(node) { this.remove(node); this.#insertAfter(this.#sentinel, node); }
  first() { return this.#size ? this.#sentinel.next : null; }
  last() { return this.#size ? this.#sentinel.prev : null; }

  *[Symbol.iterator]() {
    for (let n = this.#sentinel.next; n !== this.#sentinel; n = n.next) yield n.val;
  }
}
```

