JavaScript · JavaScript Linked Lists (Singly, Doubly, Circular) · Doubly and circular variants track
```javascript
// 2. LRU cache: Map from key to node, list ordered from most to least recent.
class LRUCache {
  #capacity;
  #map = new Map();
  #list = new DoublyList(); // node values are [key, value]

  constructor(capacity) { this.#capacity = capacity; }

  get(key) {
    const node = this.#map.get(key);
    if (!node) return -1;
    this.#list.moveToFront(node);
    return node.val[1];
  }

  put(key, value) {
    const node = this.#map.get(key);
    if (node) {
      node.val[1] = value;
      this.#list.moveToFront(node);
      return;
    }
    this.#map.set(key, this.#list.pushFront([key, value]));
    if (this.#list.size > this.#capacity) {
      const oldest = this.#list.last();
      this.#list.remove(oldest);
      this.#map.delete(oldest.val[0]); // evict from both structures together
    }
  }
}

// 3. Josephus on a circular singly linked list: the survivor when every k-th of n is removed.
function josephus(n, k) {
  const head = { val: 1, next: null };
  let tail = head;
  for (let i = 2; i <= n; i++) tail = tail.next = { val: i, next: null };
  tail.next = head; // close the circle
  let prev = tail;
  while (prev.next !== prev) {
    for (let i = 1; i < k; i++) prev = prev.next;
    prev.next = prev.next.next; // unlink the k-th node
  }
  return prev.val; // josephus(5, 2) === 3
}
```

The Map blueprint builds an LRU cache from a Map alone, using its insertion order; comparing the two versions is a good L4 discussion of when JavaScript's built-ins make a classic structure unnecessary.

