const seen = Object.create(null);
const inherited = 'constructor' in seen; // false
const counts = new Map();
for (const w of ['__proto__', 'a', '__proto__']) counts.set(w, (counts.get(w) ?? 0) + 1);
// Map { '__proto__' => 2, 'a' => 1 }
Complexity: O(1) average per operation

