  return t.map((x, i) => {
    for (let j = i + 1; j < t.length; j++) if (t[j] > x) return j - i;
    return 0;
  }); // O(n^2)
}
Correct:
function dailyTemperatures(t) {
  const ans = new Array(t.length).fill(0);
  const stack = []; // indexes whose temperatures decrease from bottom to top
  for (let i = 0; i < t.length; i++) {
    while (stack.length && t[i] > t[stack.at(-1)]) {
      const j = stack.pop();
      ans[j] = i - j;
    }
    stack.push(i);
  }
  return ans;
}
Complexity: O(n) time, O(n) space

