function diameterOfBinaryTree(root) {
  let best = 0;
  function height(node) {
    if (!node) return 0;
    const l = height(node.left), r = height(node.right);
    best = Math.max(best, l + r); // the path that bends here, counted in edges
    return 1 + Math.max(l, r);    // one branch for the parent
  }
  height(root);
  return best;
}
Complexity: O(n) time, O(h) stack

