These five snippets are the canonical answers learners should write from memory.

```javascript
// 1. Count anything (numbers, strings, NaN, objects) without changing key types.
const count = new Map();
for (const x of items) count.set(x, (count.get(x) ?? 0) + 1);

// 2. Get-or-create a list with a single lookup (grouping).
function pushTo(map, key, value) {
  let list = map.get(key);
  if (list === undefined) map.set(key, (list = []));
  list.push(value);
}

// 3. Value -> index: check before storing, so an element never pairs with itself.
function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const j = seen.get(target - nums[i]);
    if (j !== undefined) return [j, i];
    seen.set(nums[i], i);
  }
  return [];
}

// 4. Composite keys: arrays match by reference, so encode coordinates as strings.
const cell = (r, c) => `${r},${c}`;
visited.set(cell(2, 3), true);
visited.has(cell(2, 3)); // true, whereas visited.has([2, 3]) is never true

// 5. Present with the value undefined vs absent.
map.has('k');               // tells the two apart
map.get('k') === undefined; // true in both cases
```

Snippet 3 is the Blind 75 Two Sum reference solution; asking learners why the lookup must come before the `set` is a good one-question check of this whole track.

