JavaScript · JavaScript Queues and Deques · Front-end operations track
Two snippets cover the track: a small `Queue` class with occasional compaction, and the level-by-level BFS loop used throughout the corpus.

```javascript
// 1. Queue with a head index: O(1) amortised dequeue, with occasional compaction.
class Queue {
  #items = [];
  #head = 0;

  enqueue(x) {
    this.#items.push(x);
  }

  dequeue() {
    if (this.#head === this.#items.length) return undefined;
    const x = this.#items[this.#head++];
    if (this.#head > 1024 && this.#head * 2 > this.#items.length) {
      this.#items = this.#items.slice(this.#head); // drop consumed slots
      this.#head = 0;
    }
    return x;
  }

  peek() {
    return this.#items[this.#head];
  }

  get size() {
    return this.#items.length - this.#head;
  }
}

// 2. Level-by-level BFS: snapshot where the current level ends before adding children.
function levelOrder(root) {
  const levels = [];
  if (!root) return levels;
  const queue = [root];
  let head = 0;
  while (head < queue.length) {
    const levelEnd = queue.length; // everything queued so far is this level
    const level = [];
    while (head < levelEnd) {
      const node = queue[head++];
      level.push(node.val);
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    levels.push(level);
  }
  return levels;
}
```

Snippet 2 is the same algorithm as Binary Tree Level Order Traversal in the corpus; the `levelEnd` snapshot is the line to ask learners to justify.

