JavaScript · JavaScript Queues and Deques · Deque and specialised queues track
The ring-buffer deque and the monotonic deque are the two snippets learners should write from memory.

```javascript
// 1. Ring-buffer deque: O(1) amortised at both ends.
class Deque {
  #buf;
  #head = 0;
  #size = 0;

  constructor(capacity = 16) {
    this.#buf = new Array(capacity);
  }

  get size() {
    return this.#size;
  }

  pushBack(x) {
    if (this.#size === this.#buf.length) this.#grow();
    this.#buf[(this.#head + this.#size) % this.#buf.length] = x;
    this.#size++;
  }

  pushFront(x) {
    if (this.#size === this.#buf.length) this.#grow();
    this.#head = (this.#head - 1 + this.#buf.length) % this.#buf.length; // never negative
    this.#buf[this.#head] = x;
    this.#size++;
  }

  popFront() {
    if (this.#size === 0) return undefined;
    const x = this.#buf[this.#head];
    this.#buf[this.#head] = undefined; // release the reference
    this.#head = (this.#head + 1) % this.#buf.length;
    this.#size--;
    return x;
  }

  popBack() {
    if (this.#size === 0) return undefined;
    const i = (this.#head + this.#size - 1) % this.#buf.length;
    const x = this.#buf[i];
    this.#buf[i] = undefined;
    this.#size--;
    return x;
  }

  peekFront() {
    return this.#size ? this.#buf[this.#head] : undefined;
  }

  peekBack() {
    return this.#size ? this.#buf[(this.#head + this.#size - 1) % this.#buf.length] : undefined;
  }
```

