// 2. Monotonic deque: maximum of every window of size k, in O(n).
function maxSlidingWindow(nums, k) {
  const dq = new Deque(); // indices whose values decrease from front to back
  const res = [];
  for (let i = 0; i < nums.length; i++) {
    if (dq.size && dq.peekFront() <= i - k) dq.popFront();          // left the window
    while (dq.size && nums[dq.peekBack()] <= nums[i]) dq.popBack(); // can never be the max again
    dq.pushBack(i);
    if (i >= k - 1) res.push(nums[dq.peekFront()]);
  }
  return res;
}
```

The priority-queue row is a terminology lesson worth making explicit: despite the name, a priority queue does not keep arrival order, and in JavaScript it means writing or importing a heap, as in the corpus's Heap section.

