// Built-in (ES2025): each returns a new Set; a and b are unchanged.
a.union(b);               // Set {1, 2, 3, 4}
a.intersection(b);        // Set {2, 3}
a.difference(b);          // Set {1}
a.symmetricDifference(b); // Set {1, 4}
a.isSubsetOf(b);          // false

// Manual versions for older runtimes: iterate the smaller set for intersection.
const [small, big] = a.size <= b.size ? [a, b] : [b, a];
const common = new Set([...small].filter(x => big.has(x)));
const equal = a.size === b.size && [...a].every(x => b.has(x));

// Bitmask sets for a universe of at most 31 items.
let mask = 0;
mask |= 1 << 4;                       // add item 4
const hasFour = (mask >> 4) & 1;      // membership test: 1
const both = maskA & maskB;           // intersection
const onlyA = maskA & ~maskB;         // difference
const aWithinB = (maskA & maskB) === maskA; // subset
```

Bitwise operators work on 32-bit signed integers, so bit 31 makes a mask negative; beyond 31 items use `>>> 0` carefully or switch to `BigInt` masks. Pacific Atlantic Water Flow is the Blind 75 problem where the algebra is the whole answer: the result is the intersection of the cells each ocean can reach.

