These four snippets cover the patterns that do not already have a reference solution in the corpus.

```javascript
// 1. Monotonic stack of indices: next greater element for every position.
function nextGreater(nums) {
  const res = new Array(nums.length).fill(-1);
  const stack = []; // indices still waiting for a greater value; their values decrease
  for (let i = 0; i < nums.length; i++) {
    while (stack.length && nums[stack.at(-1)] < nums[i]) res[stack.pop()] = nums[i];
    stack.push(i);
  }
  return res;
}

// 2. Min stack: each entry remembers the minimum at its height.
class MinStack {
  #items = [];
  push(x) {
    const min = this.#items.length ? Math.min(x, this.#items.at(-1)[1]) : x;
    this.#items.push([x, min]);
  }
  pop() { this.#items.pop(); }
  top() { return this.#items.at(-1)[0]; }
  getMin() { return this.#items.at(-1)[1]; }
}

// 3. Recursion to an explicit stack: in-order traversal without recursion.
function inorder(root) {
  const out = [], stack = [];
  let node = root;
  while (node || stack.length) {
    while (node) { stack.push(node); node = node.left; }
    node = stack.pop();
    out.push(node.val);
    node = node.right;
  }
  return out;
}
```

