These five snippets are the canonical answers learners should write from memory.

```javascript
// 1. "Replace" the character at i: strings are immutable, so build a new one.
const setChar = (s, i, ch) => s.slice(0, i) + ch + s.slice(i + 1);

// 2. Many edits: work on an array of code points, then join once.
const chars = [...s];
chars[0] = chars[0].toUpperCase();
const edited = chars.join('');

// 3. Count lowercase ASCII letters in a 26-slot array.
const count = new Array(26).fill(0);
for (let i = 0; i < s.length; i++) count[s.charCodeAt(i) - 97]++;

// 4. Expand around a centre; after the loop the palindrome is s.slice(l + 1, r).
function expand(s, l, r) {
  while (l >= 0 && r < s.length && s[l] === s[r]) { l--; r++; }
  return s.slice(l + 1, r);
}

// 5. Every occurrence of a non-empty t in s, overlaps included.
const positions = [];
for (let i = s.indexOf(t); i !== -1; i = s.indexOf(t, i + 1)) positions.push(i);
```

