const maxDepth = node => (node ? 1 + Math.max(maxDepth(node.left), maxDepth(node.right)) : 0);

// 2. Pass down: every node must fit the bounds its ancestors impose.
function isValidBST(node, low = -Infinity, high = Infinity) {
  if (!node) return true;
  if (node.val <= low || node.val >= high) return false;
  return isValidBST(node.left, low, node.val) && isValidBST(node.right, node.val, high);
}

// 3. Combine children plus a global answer: diameter in edges.
function diameter(root) {
  let best = 0;
  const depth = node => {
    if (!node) return 0;
    const left = depth(node.left), right = depth(node.right);
    best = Math.max(best, left + right); // longest path that bends at this node
    return 1 + Math.max(left, right);    // longest path that continues up to the parent
  };
  depth(root);
  return best;
}

// 4. Two trees in step: same shape and same values.
function isSameTree(p, q) {
  if (!p && !q) return true;
  if (!p || !q || p.val !== q.val) return false;
  return isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
}
```

