Recursive versions are three lines each; the iterative versions below are what learners need for deep trees and early exits. Level order is covered in the queues blueprint.

```javascript
// Preorder: push right before left so left comes out first.
function preorder(root) {
  const out = [], stack = root ? [root] : [];
  while (stack.length) {
    const node = stack.pop();
    out.push(node.val);
    if (node.right) stack.push(node.right);
    if (node.left) stack.push(node.left);
  }
  return out;
}

// Inorder: go left as far as possible, visit, then turn right.
function inorder(root) {
  const out = [], stack = [];
  let node = root;
  while (node || stack.length) {
    while (node) { stack.push(node); node = node.left; }
    node = stack.pop();
    out.push(node.val);
    node = node.right;
  }
  return out;
}

// Postorder: a node-right-left preorder, reversed, is left-right-node.
function postorder(root) {
  const out = [], stack = root ? [root] : [];
  while (stack.length) {
    const node = stack.pop();
    out.push(node.val);
    if (node.left) stack.push(node.left);
    if (node.right) stack.push(node.right);
  }
  return out.reverse();
}
```

The postorder trick (reverse a mirrored preorder) is worth naming explicitly: it is the simplest iterative postorder, but it builds the whole output before reversing, so it cannot stop early.

