```javascript
// 1. BST insert, iteratively: compare and go one way until there is room.
function bstInsert(root, val) {
  const fresh = { val, left: null, right: null };
  if (!root) return fresh;
  let node = root;
  for (;;) {
    if (val < node.val) {
      if (!node.left) { node.left = fresh; break; }
      node = node.left;
    } else {
      if (!node.right) { node.right = fresh; break; }
      node = node.right;
    }
  }
  return root;
}

// 2. Lowest common ancestor: in a BST, walk until p and q split; in any binary tree, recurse.
function lcaBST(root, p, q) {
  let node = root;
  while (node) {
    if (p.val < node.val && q.val < node.val) node = node.left;
    else if (p.val > node.val && q.val > node.val) node = node.right;
    else return node;
  }
  return null;
}
function lca(node, p, q) {
  if (!node || node === p || node === q) return node;
  const left = lca(node.left, p, q), right = lca(node.right, p, q);
  return left && right ? node : left ?? right;
}

// 3. Height-balanced check in one pass: -1 means "already unbalanced below".
function isBalanced(root) {
  const height = node => {
    if (!node) return 0;
    const l = height(node.left);
    if (l === -1) return -1;
    const r = height(node.right);
    if (r === -1 || Math.abs(l - r) > 1) return -1;
    return 1 + Math.max(l, r);
  };
  return height(root) !== -1;
}
```

