This class is the canonical implementation; every pattern in section 3 builds on its `find` method.

```javascript
class TrieNode {
  children = new Map(); // character -> TrieNode
  end = false;          // true when a word stops here
  pass = 0;             // number of stored words whose path goes through this node
}

class Trie {
  #root = new TrieNode();

  insert(word) {
    if (this.search(word)) return; // keep pass counts exact on duplicates
    let node = this.#root;
    node.pass++;
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, new TrieNode()); // create only if missing
      node = node.children.get(ch);
      node.pass++;
    }
    node.end = true;
  }

  find(prefix) { // the node at the end of prefix, or null
    let node = this.#root;
    for (const ch of prefix) {
      node = node.children.get(ch);
      if (!node) return null;
    }
    return node;
  }

  search(word) { return this.find(word)?.end === true; }
  startsWith(prefix) { return this.find(prefix) !== null; }
  countWithPrefix(prefix) { return this.find(prefix)?.pass ?? 0; }
```

