    if (!this.search(word)) return false;
    let node = this.#root;
    node.pass--;
    for (const ch of word) {
      const child = node.children.get(ch);
      if (--child.pass === 0) { // no other word uses this branch: drop it whole
        node.children.delete(ch);
        return true;
      }
      node = child;
    }
    node.end = false;
    return true;
  }
