// 1. Wildcard search: '.' matches any one character (Design Add and Search Words).
function matches(node, word, i = 0) {
  if (i === word.length) return node.end;
  const ch = word[i];
  if (ch === '.') {
    for (const child of node.children.values()) if (matches(child, word, i + 1)) return true;
    return false;
  }
  const child = node.children.get(ch);
  return child ? matches(child, word, i + 1) : false;
}
