// 3. Autocomplete: up to `limit` words under a prefix, in alphabetical order.
function complete(trie, prefix, limit = 5) {
  const start = trie.find(prefix);
  const out = [];
  const dfs = (node, path) => {
    if (!node || out.length >= limit) return;
    if (node.end) out.push(prefix + path);
    const letters = [...node.children.keys()].sort();
    for (const ch of letters) dfs(node.children.get(ch), path + ch);
  };
  dfs(start, '');
  return out;
}
```

The pruning line in snippet 2 is what makes Word Search II fast on large dictionaries: once every word under a branch has been found, the branch disappears and the board search stops entering it.

