Four snippets cover the variants learners use most. Each was tested: the label class on merged emails, Number of Islands on the LeetCode examples, Kruskal on a four-node graph and a disconnected one, and the ratio class on chained and unrelated equations.

```javascript
// 1. Label keys: a Map parent, created lazily.
class LabelUnionFind {
  #parent = new Map();
  find(x) {
    if (!this.#parent.has(x)) this.#parent.set(x, x);
    let root = x;
    while (this.#parent.get(root) !== root) root = this.#parent.get(root);
    while (this.#parent.get(x) !== root) { // full path compression
      const next = this.#parent.get(x);
      this.#parent.set(x, root);
      x = next;
    }
    return root;
  }
  union(a, b) {
    const ra = this.find(a), rb = this.find(b);
    if (ra === rb) return false;
    this.#parent.set(ra, rb);
    return true;
  }
}

// 2. Number of Islands with union-find: islands = land cells - successful merges.
function numIslands(grid) {
  const rows = grid.length, cols = grid[0].length;
  const uf = new UnionFind(rows * cols);
  let land = 0, merges = 0;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] !== '1') continue;
      land++;
      if (r + 1 < rows && grid[r + 1][c] === '1' && uf.union(r * cols + c, (r + 1) * cols + c)) merges++;
      if (c + 1 < cols && grid[r][c + 1] === '1' && uf.union(r * cols + c, r * cols + c + 1)) merges++;
    }
  }
  return land - merges;
}
```

