// 3. Kruskal's MST: sort edges by weight, keep the unions that succeed.
function minSpanningTree(n, edges) { // edges are [u, v, weight]
  const uf = new UnionFind(n);
  let total = 0, used = 0;
  for (const [u, v, w] of [...edges].sort((a, b) => a[2] - b[2])) {
    if (uf.union(u, v)) {
      total += w;
      if (++used === n - 1) break;
    }
  }
  return used === n - 1 ? total : -1; // -1: the graph is disconnected
}
