Correct:
const byN = (a, b) => {
  const x = a.n ?? Infinity, y = b.n ?? Infinity; // missing values last
  return x < y ? -1 : x > y ? 1 : 0;
};
const rows = [{ n: 3 }, {}, { n: 1 }, { n: 2 }].sort(byN);
Complexity: O(n log n) time

