Correct:
function searchMatrix(m, t) {
  if (!m.length || !m[0].length) return false;
  let r = 0, c = m[0].length - 1;
  while (r < m.length && c >= 0) {
    if (m[r][c] === t) return true;
    if (m[r][c] > t) c--; else r++;
  }
  return false;
}
Complexity: O(m + n) time, O(1) space

